std::vector<long long> countSetBits(std::vector<long long> numbers) {
    std::vector<long long> out;
    for (std::size_t i = 0; i < numbers.size(); ++i) {
        unsigned long long v = (unsigned long long)numbers[i];
        long long count = 0;
        while (v) { v &= v - 1ULL; ++count; }
        out.push_back(count);
    }
    return out;
}

